insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 1, 'Where does a learner run the practicals of this course?', '["In a Suite tendering app that opens beside the lesson with the Ekene bids already loaded into it.", "In the course''s own calculator panels, which call the same vendored engine the lessons quote.", "On a spreadsheet template the learner downloads and fills in by hand.", "Against a stored answer sheet the panel looks up by bid code."]'::jsonb, 1, 'This is an engine course with no Suite app: the envelope calculator, the award calculator and the contract calculator each call engines/supplychain/tender.js on the learner''s own bids and settings. There is no downloaded template, and the panel computes every figure on the inputs given, so a learner''s own bids run as readily as the Ekene ones.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 2, 'In what order does a two-envelope evaluation take its stages?', '["Price envelopes of every bid first, so that the committee can set a pass mark from the spread of prices.", "Pass mark first, then the mandatory requirements of the bids that cleared it, and the award last of all.", "Both envelopes of each bid at once, with price as one more criterion.", "Mandatory requirements, the pass mark, the price envelopes of the passing bids, then the award."]'::jsonb, 3, 'The engine''s stages basis reads: technical envelope (mandatory requirements, then the pass mark), then the commercial envelope of the passing bids only, then the award. Opening prices first defeats the purpose of sealing them, a mandatory failure is found before any scoring, and price is never a technical criterion in this process.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 3, 'WS4 quotes 763200.000000, the lowest total of the six well services bids, and scores 65.000000 against a pass mark of 70. What becomes of its price?', '["It is never opened, so none of its figures enters a later stage.", "It is opened and ranked first on cost, since a low price outweighs a narrow technical miss of five points.", "Its price is held in reserve and opened if the award to a passing bid later falls through for any reason.", "It lowers the average that prices WS3''s missing nitrogen, although WS4 itself cannot be awarded."]'::jsonb, 0, 'Only passing bids have their commercial envelope opened (World Bank Procurement Regulations (7th ed.) para 6.29; Public Procurement Act 2007 s.51(2)). WS4 fails at 65.000000, so its price is never read: it cannot rank on cost, nothing is held in reserve, and its nitrogen line does not reach the average, which uses the other responsive bids only.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 4, 'Which edition of the World Bank Procurement Regulations for IPF Borrowers does this course read?', '["The February 2025 edition, published together with the Guidance on Evaluating Bids and Proposals.", "The edition in the Official Gazette of 19 June 2007, which the Nigerian Act adopts by reference.", "The Seventh Edition, September 2025.", "Whatever edition the tender committee holds, because the engine records no edition in its citations."]'::jsonb, 2, 'The sources table names the Regulations as the Seventh Edition, September 2025, read on 2026-09-26. February 2025 is the edition of the Guidance and of the Goods SPD, the 2007 gazette date belongs to the Public Procurement Act, and the engine''s own citation carries the edition as (7th ed.).'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 5, 'The materials tender''s criteria name API 5CT and API 6D data sheets. How does the course treat those texts?', '["Its lessons quote their acceptance limits, which specification is scored against.", "The Public Procurement Act 2007 takes their place and sets casing specifications.", "It names them by number and quotes none of their text, because they are paid standards.", "Each clause the criteria cite is printed, as for any public text."]'::jsonb, 2, 'Licensed texts are never quoted: the API numbers are named as the bidders'' specification and taught by concept. The Public Procurement Act sets no product specification, and the API standards are paid texts, so no clause is printed.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 6, 'The engine returns WS4 with the status fail-pass-mark and a reason. How does the course describe that outcome?', '["As a result returned with a reason: WS4 is excluded and the other bids go on.", "A refusal, because the engine declined to open the commercial envelope of the bid.", "An error object whose field is passMark.", "A hidden warning the panel shows only when asked."]'::jsonb, 0, 'A refusal is an object with error and field, returned when an input is bad, and no result comes back with it. A bid excluded at a stage is a result with its reason beside it, so the course says it was excluded, or returned with the reason. The panel prints every reason in the engine''s words.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 7, 'Which settings does the engine refuse by name when they are missing, saying there is no default?', '["Only the pass mark; the technical weight falls back to 0.7, the figure the well services tender states.", "The arithmetic tolerance, since 0.005 is never assumed and each bill must carry a tolerance of its own.", "The omission rule, since no omitted item can be priced until one is chosen.", "The pass mark, the technical weight, the price and technical methods, and the award basis."]'::jsonb, 3, 'The refusal table shows the pass mark, the technical weight, the price and technical methods and the award basis each refused with the words there is no default. The technical weight has no fallback. The tolerance is left out safely, as 0.005 applies when none is stated, and the omission rule defaults to the average of ITB 34.1.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 8, 'A tender''s five criterion weights sum to 99. What does the technical envelope return?', '["Scores computed with every weight scaled up so the percentages reach 100.", "A refusal naming the field criteria: \"criteria weights must sum to 100; they sum to 99\".", "A result scored as given, with the pass mark lowered by one point.", "Bids scored after the missing point is added to methodology."]'::jsonb, 1, 'The engine reads weights as percentages and requires a sum of 100 within 1e-9; any other sum is refused with the message quoted, in the engine''s own words. It rescales nothing, moves no pass mark and assigns no missing point, since each of those would be a decision the tender never stated.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 9, 'A learner types mean-deviation as the price method of a combined award. What does the engine return?', '["A refusal naming priceMethod, since the engine scores price by two named methods only.", "A combined score in which each bid''s price is scored by its distance from the mean evaluated cost.", "The lowest-ratio score, applied as the method the tender states.", "A ranking on the technical percentage alone, with the price dropped."]'::jsonb, 0, 'The engine''s message, in its own words, is "priceMethod must be ''lowest-ratio'' or ''linear''; there is no default". It computes no mean-deviation score, substitutes no method it was not given and never drops a term silently; a refused input returns no ranking at all.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 10, 'What is true of the bidders WS1 to WS6 and MS1 to MS5?', '["Anonymised contractors from an Ekene tender held in 2027, with their real prices kept.", "Firms on a national contractor register, renamed so that no bid can be traced back.", "They are codes in synthetic fixtures written by a stated script.", "Sample bids taken from the World Bank Guidance (February 2025) and moved onto the Ekene wells."]'::jsonb, 2, 'Every Ekene tender, bidder, price and score is synthetic, written for this platform by a stated script that reproduces the files byte for byte, and each file is labelled SYNTHETIC. No real company, tender or price list appears, and the Guidance''s worked examples are separate cases the course recomputes on their own.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 11, 'What makes a figure a gradable answer in this course?', '["A value read from a published worked example, entered to two decimals as the Guidance prints it.", "Any figure within a tolerance the learner states when submitting it.", "An estimate of what the job will cost, checked against the final account.", "It is a value the engine returns on bids, criteria and settings stated in advance, entered to six decimals."]'::jsonb, 3, 'Every graded number is a return value of the engine on fixed inputs, so the same inputs give the same number on any machine and each graded figure is quoted to six decimals as the panel prints it. Printed examples round to two decimals, a learner never states a tolerance, and an evaluated cost ranks bids without forecasting the job''s cost.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 12, 'At the commercial stage of the well services tender, which bids are responsive in this course''s sense?', '["All six bids, because every one of them answered the invitation before the closing time.", "WS1, WS2, WS3 and WS5, the four that passed the technical envelope with no rejection.", "WS1 to WS5, since WS4 answered every criterion and was scored at 65.000000 like the rest.", "Only WS3 and WS5, the two bids that win an award."]'::jsonb, 1, 'Responsive names a bid still in the evaluation at that stage: it passed the technical envelope and was not rejected at the commercial stage. WS6 failed a mandatory requirement and WS4 fell below the pass mark, so neither is responsive there, whatever it answered. Winning an award is a separate matter from staying in the evaluation.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 13, 'Which sentence uses the term lowest evaluated cost as this course legislates it?', '["WS4 holds it, because 763200.000000 is the lowest total quoted by any of the six well services bids.", "WS2 and WS5 share it, each quoting 849400.000000 before correction.", "WS1 holds it once its discount of 15000.000000 is deducted.", "WS5 holds it, at 862141.000000, with omissions at the average and the fixture''s schedule."]'::jsonb, 3, 'The lowest evaluated cost is built by the engine from the corrected price, discount, deviations, omissions and schedule, and it is never a quoted price. WS4''s price is never opened, WS2 and WS5 part once WS2''s bill is corrected, and WS1''s figure of 928200.000000 ranks third.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 14, 'Which figure in the engine is an engine convention that no cited text states?', '["The arithmetic tolerance of 0.005, half a cent, used when a call states no tolerance.", "Unit rate prevailing over the amount a bidder writes beside it on a line of the bill.", "Pricing an item a bid omits at the average of the prices the other responsive bids quote.", "Opening a price only after the technical scoring is complete."]'::jsonb, 0, 'The course names the tolerance 0.005 (half a cent) as an engine convention, stated in the basis. The unit rate rule comes from ITB 35.1 of the Works SPD, the average from ITB 34.1, and the two-envelope order from para 6.29 of the Regulations with s.48 and s.51(2) of the Public Procurement Act 2007.'),
  ('procurement', 'beginner', 'module', 'm01-what-a-tender-evaluation-decides', 15, 'What does every refusal from the engine carry?', '["A partial result for the valid bids, with any bid holding a bad input dropped without a word.", "An error and the field it refuses, with a message that begins with that field''s name.", "Defaults put in place of the bad input, with a warning.", "Numbered error codes to look up in a table of codes."]'::jsonb, 1, 'Every function returns either a result or an object with error and field, where field names the input refused and the message starts with that name and states the exact condition that failed. The engine drops nothing silently, supplies no default for a refused input, and uses messages with no numbered codes.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 1, 'WS6 meets bid-security and does not meet signed-bid-form. What does the technical envelope return for it?', '["Its scores are computed, and its price envelope is opened only if it clears the mark of 70.", "A pass, since four of its five criterion scores are 4 and its proposal is the strongest on paper.", "The status fail-mandatory: it is never scored and its price stays sealed.", "A refusal naming bids[5].mandatory, as an invalid input."]'::jsonb, 2, 'A bid that fails a mandatory requirement is excluded before it is scored, with the reason "failed the mandatory requirement signed-bid-form; the bid is not scored and its commercial envelope is not opened". Its scores are never read, however strong, and the exclusion is a result with a reason, so no field is refused.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 2, 'The technical envelope returns two figures for WS1. Which pair does it return?', '["82.500000 percent and 330.000000 weighted points.", "330.000000 percent and 82.500000 weighted points, the two figures read the other way round.", "An identical 82.500000 for both, since the weighted points are the same sum as the percentage.", "A technical score of 97.058824 percent and 330.000000 weighted points for the bid."]'::jsonb, 0, 'technicalPercent is the sum of weight x score / maxScore, 82.500000 for WS1; weightedPoints is the sum of weight x score, 330.000000, with no division by the maxScore of 4. The two differ by that factor. 97.058824 is WS1''s relative technical score St in the combined score, a different figure built later from the percentage.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 3, 'WS5 scores exactly 70.000000 on a tender whose pass mark is 70. What happens to it?', '["It fails, because a bid must score strictly above the pass mark for its price to be opened.", "It passes, and its price envelope is opened.", "A committee decides it.", "Its status becomes fail-pass-mark with the reason that 70 is not above the pass mark 70."]'::jsonb, 1, 'The engine''s basis reads "a bid passes when technicalPercent >= 70": the test is greater than or equal, so a bid at the pass mark passes. WS5 goes on to hold the lowest evaluated cost. The engine leaves no bid undecided, and no reason of the kind described exists.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 4, 'WS3 scores 4 of 4 on personnel, a criterion weighted 25. What term does personnel add to WS3''s technical percentage?', '["100.000000, the weight times the score before any division by the maxScore of 4 is made.", "18.750000, three quarters of the weight, which is the personnel term that WS1 earns.", "22.500000, the term that WS3 earns on methodology, where it scores 3 of a possible 4.", "25.000000, the whole weight of the criterion."]'::jsonb, 3, 'Each term is weight x score / maxScore: 25 x 4 / 4 = 25.000000. 100.000000 is the weighted points term, with no division by maxScore. 18.750000 is 25 x 3 / 4, which WS1 earns on personnel, and 22.500000 is WS3''s methodology term, 30 x 3 / 4.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 5, 'WS4 is scored at 65.000000 against a pass mark of 70. How does the engine report it?', '["Status fail-pass-mark, with the reason \"technical score 65 is below the pass mark 70; the commercial envelope is not opened\".", "A refusal naming passMark, since a bid that scores below the mark counts as an invalid input to the call.", "Status pass with a flag, because 65.000000 lies within five points of the mark and is close enough to open.", "Status fail-mandatory, as a bid below the pass mark is treated like one that failed a requirement."]'::jsonb, 0, 'WS4 is scored and falls short, so the engine returns fail-pass-mark with the reason quoted, in its own words. A score below the mark is a result with its reason and no invalid input, there is no margin of closeness in the rule, and fail-mandatory is kept for a failed requirement, which WS4 did not have.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 6, 'Stated as a test, WS1 fails both bid-security and signed-bid-form. What reason does the engine give?', '["Only bid-security, the first requirement it failed, since the engine stops checking at the first failed requirement and names that one alone.", "A separate reason for each failed requirement, printed on separate rows, so that WS1 appears twice in the list of bids the technical envelope excludes.", "It names both: \"failed the mandatory requirements bid-security, signed-bid-form; the bid is not scored and its commercial envelope is not opened\".", "A technical percentage of 0.000000 and the status fail-pass-mark, since no requirement counted and every criterion score is then read as zero."]'::jsonb, 2, 'When a bid fails more than one requirement the engine names every failed requirement in one reason, so the report to the bidder is complete. It does not stop at the first, it lists the bid once, and a mandatory failure is never scored, so there is no percentage and no fail-pass-mark status.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 7, 'An evaluator leaves WS1''s hse score blank. What does the technical envelope do?', '["Zero is taken for hse, which gives WS1 a technical percentage of 71.250000 in place of 82.500000.", "It refuses: \"bids[0].scores.hse must be a number from 0 to 4 (the criterion''s maxScore)\".", "It rescales the four criteria that were scored so that their weights again sum to 100.", "WS1 is excluded as fail-mandatory, with the missing hse score named as the failed requirement."]'::jsonb, 1, 'A missing score is refused with the same message as a score out of range, in the engine''s own words. The engine never treats a blank as zero, which would sink a bid on a clerical slip (82.500000 less the hse term of 11.250000 would give 71.250000). It does not rescale the weights either, and a score is no mandatory requirement.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 8, 'A score of 5 is typed for WS1''s methodology, a criterion with a maxScore of 4. What comes back?', '["WS1 scores above 100 percent, and the panel prints the excess as a bonus beside the pass mark.", "The score is capped at 4 without a word.", "Each bid''s methodology scale is raised to 5.", "The call is refused, and the message names methodology and its scale of 0 to 4."]'::jsonb, 3, 'A score above its criterion''s maxScore is refused, naming the criterion: bids[0].scores.methodology must be a number from 0 to 4. The engine caps nothing silently, changes no scale on its own, and a technical percentage cannot exceed 100.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 9, 'The Guidance''s Figure IX scores Company A 2, 2, 2 and 1 on criteria weighted 50, 25, 15 and 10, each out of 4. Which engine figure matches the printed 190?', '["The technical percentage, which the engine returns as 190.000000 for Company A.", "Neither of the two, since the Guidance prints weighted points to two decimals only.", "Both of them, because on a scale of 4 the percentage and the points always agree.", "The weighted points, 190.000000."]'::jsonb, 3, 'Weighted points are the sum of weight x score, the total the World Bank Guidance (February 2025) prints in Figure IX, and the engine returns 190.000000 against the printed 190. The technical percentage divides each term by its maxScore and is 47.500000. On a scale of 4 the points are four times the percentage, so the two share an order and differ in value.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 10, 'On the materials tender, with a pass mark of 60, which bid fails?', '["MS5, at 50.000000, whose price is never opened.", "MS4, at 68.750000, the lowest of the five scores and so the one below the mark.", "No bid fails, since every materials bid meets both of its mandatory requirements.", "MS2, at 71.250000, which misses the mark once its after-sales score of 2 is counted."]'::jsonb, 0, 'The engine returns MS5 at 50.000000 with the reason "technical score 50 is below the pass mark 60; the commercial envelope is not opened". MS4''s 68.750000 is above 60 and is not the lowest score, meeting every mandatory requirement does not pass the pass mark, and MS2''s 71.250000 clears 60.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 11, 'The Guidance''s Annex 2 scores companies in points out of 15, 15 and 70 against a threshold of 80. On its printed criterion scores, which company passes?', '["B and C, since B''s 77.000000 rounds up to the threshold once the scores are weighted.", "All three, since the threshold applies criterion by criterion.", "C alone, at 91.000000, with A at 59.000000 and B at 77.000000 below the threshold.", "A and C, as A''s 48 points outweigh its first two scores."]'::jsonb, 2, 'On the Annex 2 scores of the World Bank Guidance (February 2025), with weights equal to the maximum points, the technical percentage equals the points total: A 59.000000, B 77.000000, C 91.000000. Only C reaches 80, so the engine returns fail-pass-mark for A and B. Nothing rounds 77.000000 up, the threshold applies to the total, and A''s total is lowest of the three.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 12, 'Why does the engine require the criterion weights to sum to 100?', '["Because the pass mark is fixed at 100 points and the weights must add up to meet it.", "It reads the weights as percentages of the technical judgement, checked to within 1e-9.", "So that weighted points and the technical percentage return the same figure for each bid.", "Because the World Bank Guidance (February 2025) requires every tender to use exactly five criteria."]'::jsonb, 1, 'WEIGHT_SUM is 100 and WEIGHT_SUM_TOLERANCE is 1e-9: the weights are percentages, and the tolerance absorbs binary rounding. The pass mark is a stated input with no default, weighted points differ from the percentage by the maxScore, and the materials tender has three criteria.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 13, 'On the well services tender, how do each bid''s weighted points relate to its technical percentage?', '["They are four times the percentage, because every criterion there is scored out of 4, so both give one order.", "Each term is divided by the weight, so a heavy criterion counts for less in the points total.", "The two can order bids differently, which is why the pass mark is set on the points total.", "Exactly equal, as WS5''s 280.000000 points against 70.000000 percent show."]'::jsonb, 0, 'Weighted points skip the division by maxScore, and on the well services scale every maxScore is 4, so the points are four times the percentage (WS5: 280.000000 and 70.000000) and the maximum is 400. Nothing divides by the weight, the two figures give the same order there, and the pass mark applies to the technical percentage.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 14, 'A bid''s mandatory entry carries an id and no met flag. What does the engine do?', '["It reads the missing flag as met and scores the bid, since nobody recorded a failure against it.", "It reads the missing flag as not met and returns the bid as fail-mandatory with that id named.", "Ignoring the entry, it scores the bid.", "It refuses the entry, because it will not assume a requirement was met."]'::jsonb, 3, 'The engine''s message is "bids[0].mandatory[0] must be { id: a non-empty string, met: true or false }". It assumes neither met nor not met, and it does not drop the entry. Only a bid with no mandatory list at all is simply scored, since the list is optional when not given.'),
  ('procurement', 'beginner', 'module', 'm02-the-technical-envelope', 15, 'What technical percentage does the engine return for WS6?', '["0.000000, as for a bid meeting no criterion.", "None: WS6 is never scored, so its row carries null.", "65.000000, the figure a failed bid is given so that WS4 and WS6 rank level.", "A hidden figure from its scores."]'::jsonb, 1, 'WS6 fails a mandatory requirement and is excluded before scoring, so its technicalPercent and weightedPoints are null. A null is different from a percentage of zero, which a scored bid could earn. 65.000000 is WS4''s own score, and the engine computes nothing for WS6 to hide.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 1, 'WS2 prices 18 days of the coiled tubing spread at 27000.000000 a day and writes the amount as 468000.000000. Which figure stands?', '["The written amount stands, since 468000.000000 is the figure the bidder signed and the bid form carries it into the total.", "Neither figure stands: the line is struck and priced as an omission at the average of the other bids.", "The lower of the two figures stands, so that the company never pays more than the line''s lower reading.", "The unit rate stands, and the engine corrects the line amount to 486000.000000 because 18 x 27000 is that figure."]'::jsonb, 3, 'The unit rate prevails unless the decimal point in it is obviously misplaced (ITB 35.1(a)), and no decimalMisplaced flag is recorded on WS2''s line, so the engine returns "the unit rate prevails and the amount is corrected to 486000". Nothing is struck or priced as an omission, and the rule picks the rate whatever its direction.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 2, 'After its ct-spread line is corrected, what is WS2''s corrected total?', '["849400.000000, the quoted total, since totals are carried as the bidder wrote them.", "867400.000000", "486000.000000, the corrected amount of the one line found in discrepancy.", "885574.000000, the bid''s figure after its deviation and its weeks are added."]'::jsonb, 1, 'The corrected total is the sum of the corrected lines: 849400.000000 plus the 18000.000000 correction on ct-spread gives 867400.000000. The quoted total is what the check replaces, 486000.000000 is one line, and 885574.000000 is WS2''s evaluated cost, built later from the corrected price.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 3, 'WS5 types its acid unit rate as 13.8 on 60 m3 and writes the amount as 82800.000000, and the evaluator records decimalMisplaced on the line. What does the engine do?', '["The quoted amount governs and the rate is corrected to 1380.000000.", "The unit rate governs, and the acid line is cut to 828, which WS5 must then honour.", "WS5 is rejected at the commercial stage for an obvious error in its priced bill.", "The acid line is struck and priced at the average."]'::jsonb, 0, 'With decimalMisplaced true on a line in discrepancy, the engine returns "the quoted amount governs and the unit rate is corrected to 1380", the amount divided by the quantity. The unit rate rule would have cut the line to 828, which is why the exception exists; the bid is not rejected and nothing is priced as an omission.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 4, 'What is WS5''s arithmetic correction after its acid line is read?', '["18000.000000, the same correction that WS2''s bill receives on ct-spread.", "82800.000000, the full amount of the acid line that the rate replaced.", "0.000000, so its total stays at 849400.000000", "12741.000000"]'::jsonb, 2, 'When the quoted amount governs, the amount stays and only the unit rate changes, so the corrected total equals the quoted total and the correction is 0.000000. 18000.000000 is WS2''s correction, the acid amount is unchanged, and 12741.000000 is WS5''s completion-time adjustment, a later term of its evaluated cost.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 5, 'How does the engine know that a unit rate''s decimal point is obviously misplaced?', '["It reads the flag decimalMisplaced true, stated on that bill line.", "By testing whether the gap is a power of ten.", "From the bid''s stated total, whenever it differs from the lines by more than 0.005.", "It never knows; every misplaced point is read as an ordinary unit-rate slip."]'::jsonb, 0, 'decimalMisplaced is an input on the bill line, which the evaluator records once the Employer judges the point obviously misplaced (ITB 35.1(a)), and the engine applies the exception only where the flag is stated true on a line already in discrepancy. It does not guess from the size of the gap. A stated total that differs from its lines is a separate check where the subtotals prevail, and without the flag a gap above the tolerance triggers the unit rate rule.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 6, 'decimalMisplaced is set to true on a line whose quantity is 0. What does the engine return?', '["A corrected unit rate of zero for the line, since any quoted amount divided across no units is taken as nothing.", "The line left as quoted with no reason printed, because a decimalMisplaced flag on a quantity of 0 changes nothing.", "Silence: the flag is dropped from the line without a word, and the rule that the unit rate prevails applies as usual.", "A refusal: \"lines[0].quantity must be above 0 when decimalMisplaced is true (the unit rate is corrected as quoted amount / quantity)\"."]'::jsonb, 3, 'The corrected rate is the quoted amount divided by the quantity, and that division has no meaning at zero, so the engine refuses the line in the words quoted, its own. It sets no rate, leaves nothing silently, and drops no flag.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 7, 'With a stated tolerance of 0.5, a line reads 1 x 100.5 against a quoted 100. What does the engine return?', '["A corrected amount of 100.750000 under the rule that the unit rate prevails.", "100.5, since any gap is corrected.", "No correction: a gap equal to the tolerance is no discrepancy.", "A refusal naming tolerance, because the gap and the tolerance coincide."]'::jsonb, 2, 'The rule reads greater than: a line is in discrepancy when the gap exceeds the tolerance. At a gap of 0.5 and a tolerance of 0.5 the engine returns 100.000000 with rule null. 100.750000 is the corrected amount of the second stated line, 1 x 100.75, whose gap of 0.75 is above the tolerance, and nothing is refused.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 8, 'When a call states no tolerance, what gap puts a bill line in discrepancy?', '["Any gap of one currency unit or more, as ITB 35.1 sets it.", "Any gap above 0.005, half a cent, an engine convention.", "Any gap at all, because the default tolerance is zero, so every trace of rounding counts.", "A gap above 0.5, the tolerance the course states for its boundary test of two lines."]'::jsonb, 1, 'ARITHMETIC_TOLERANCE is 0.005, used when tolerance is left out, and the course names it as an engine convention: no cited text states a tolerance. A tolerance of zero would count binary rounding as an error, and 0.5 is the stated tolerance of one boundary test.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 9, 'Stated as a test, WS1''s lines sum to 943200 but the bid states a total of 940000. What does the engine do?', '["Every line is scaled down in proportion so that 940000 stays the bid''s price.", "It takes the lines, so the total is 943200.000000 and the correction 3200.000000.", "A stated total governs the lines beneath it, so 940000 is kept.", "It rejects WS1 as nonresponsive for a total that disagrees with its own bill."]'::jsonb, 1, 'The engine''s reason is "the quoted total 940000 differs from the sum of the quoted lines 943200 by more than 0.005; the subtotals prevail". The corrected total is the sum of the corrected lines, so no line is scaled, the stated total does not govern, and the bid is corrected without rejection.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 10, 'Stated as a test, 60 m3 at 1380 is quoted as 82800 with decimalMisplaced set to true. How many lines does the engine correct?', '["One, since a line flagged as misplaced always has its rate recomputed from the amount.", "One, the acid line, which is struck and priced at the average of the other bids.", "All six, because a flag on any line sends the whole bill back for correction.", "None."]'::jsonb, 3, 'A decimalMisplaced flag on a line with no discrepancy changes nothing: 60 x 1380 is 82800, so the gap is zero and the engine corrects 0 lines. The flag only decides which figure governs when a line is already in discrepancy, and it never touches another line.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 11, 'Which texts does the course name for the rule that the unit rate prevails?', '["ITB 35.1 of the SPD for Works, two-envelope (September 2025); the 2007 Act s.31(4) permits it.", "ITB 34.1 of the SPD for Works, two-envelope (September 2025), and s.32(3) of the Public Procurement Act 2007.", "Para 6.29 of the Regulations (Seventh Edition, September 2025), which opens the commercial envelope.", "The Guidance on Evaluating Bids and Proposals (February 2025), Annex 3 on comparative scoring."]'::jsonb, 0, 'The engine cites the World Bank SPD Request for Bids, Works, two-envelope (Sep 2025) ITB 35.1(a) and (b), and the Public Procurement Act 2007 s.31(4) permits correction. ITB 34.1 and s.32(3) cover omitted items, para 6.29 the two envelopes, and Annex 3 is a worked combined score.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 12, 'A bid''s amount in words differs from its amount in figures. What does the engine compute for that?', '["Words govern, and the engine corrects the figure to match them.", "Figures govern whenever the gap exceeds the tolerance of 0.005.", "Nothing; ITB 35.1(c) is taught as a concept only.", "The lower of the two amounts, which the report then flags."]'::jsonb, 2, 'The engine compares no amount in words against figures; the course names ITB 35.1(c) and grades nothing on it. It has no text field for words at all, so it cannot correct toward either reading, and the tolerance applies only to quantity times unit rate against the quoted amount.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 13, 'A learner renames a second bill line so that two lines both carry the id mob. What comes back?', '["A refusal in the engine''s words: \"lines[1].id repeats the id ''mob''\".", "Both lines are priced, with the second one renamed to mob-2 by the engine.", "The two mob lines are merged into one.", "Only the first mob line is kept."]'::jsonb, 0, 'Every correction must name its line, and two lines with one name cannot be told apart in a report, so the engine refuses a repeated id and names the line that repeats it. It renames nothing, merges nothing and drops nothing silently.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 14, 'WS2 and WS5 both quote 849400.000000. After arithmetic correction, which statement holds?', '["Both stand at 849400.000000, as neither correction moves a total.", "WS2 stands at 867400.000000 and WS5 stays at 849400.000000.", "Both rise to 867400.000000, because each has one line corrected.", "WS5 falls to 828 on acid while WS2 keeps its quoted total."]'::jsonb, 1, 'WS2''s ct-spread line is corrected by the unit rate rule and its total rises by 18000.000000; WS5''s acid line is corrected by the misplaced decimal exception, where the amount governs, so its total does not move. The two bids, level as quoted, part at this stage.'),
  ('procurement', 'beginner', 'module', 'm03-arithmetic-correction', 15, 'Can an arithmetic correction raise a bid''s price?', '["No, as a correction only removes an error that favoured the bidder.", "No, because the rule caps a corrected total at the quoted total.", "Only when the bidder asks for it in writing before opening.", "Yes: WS2''s price goes up when its unit rate prevails on ct-spread."]'::jsonb, 3, 'Arithmetic correction is no penalty and no gift: it restores what the bid''s own rates say. On WS2 it raises the total from 849400.000000 to 867400.000000. No cap on the quoted total exists in the rule, and the bidder''s consent is not an input to it.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 1, 'Which terms does the engine add to the corrected price to build a well services bid''s evaluated cost?', '["Less the discount, plus priced deviations, omissions and the completion-time adjustment.", "Plus the discount, less priced deviations, with omissions left out.", "The quoted total''s gap from the lowest bid, plus the arithmetic correction a second time.", "Only the completion-time adjustment."]'::jsonb, 0, 'The engine''s rule is corrected price less discount plus priced deviations plus omissions plus the schedule adjustment, with a further term the well services tender does not use. A discount lowers the figure and a deviation raises it, the correction is already inside the corrected price, and no term measures a gap to another bid.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 2, 'WS1 quotes 943200.000000 with an unconditional discount of 15000.000000 and finishes in the minimum 6 weeks. What is its evaluated cost?', '["943200.000000, as a discount changes only the final contract sum.", "No figure until the committee judges whether the discount is genuine.", "928200.000000", "885574.000000"]'::jsonb, 2, 'The engine deducts an unconditional discount from the corrected price: 943200.000000 less 15000.000000 is 928200.000000, and at 6 weeks there is no completion adjustment. A discount is certain, so it counts in the comparison. 885574.000000 is WS2''s evaluated cost, and nothing in the rule adds a discount back.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 3, 'WS3 omits nitrogen. The other responsive bids price it at 33600.000000, 35400.000000 and 37200.000000. What does the engine add to WS3?', '["33600.000000, the lowest of the three, which gives WS3 the benefit of the doubt.", "No price until an estimate is stated.", "Nothing, because a bid that omits an item is held to have included it in another line.", "35400.000000, the average of the three"]'::jsonb, 3, 'The engine''s reason is "item nitrogen omitted; the average of the 3 prices quoted by the other responsive bids, 35400, is added", following ITB 34.1 of the Works SPD (September 2025). The average is the cited rule; the engine offers no lowest option (asked for one, it refuses), nothing sums the three, and an omission is priced in and not assumed away.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 4, 'WS4 also quotes a nitrogen line. Why is its price left out of the average that prices WS3''s omission?', '["WS4''s nitrogen line was corrected, and corrected amounts are left out of the average.", "WS4 failed the pass mark, so its price envelope was never opened and it is not responsive.", "The average takes three prices at most, the three received first by the tender box.", "WS4 quoted the lowest total of the six, and the lowest bid is excluded to keep the average fair."]'::jsonb, 1, 'Only responsive bids price an omission: an omitted item is priced at the average of the corrected amounts quoted for it by the other responsive bids. WS4 fell below the pass mark, so its price was never read. The average uses corrected amounts, has no cap on its count, and excludes no bid for being low.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 5, 'WS2 asks for payment in 30 days where the conditions give 60. How does the engine treat that departure?', '["A major deviation, which rejects WS2 at the commercial stage for refusing the terms.", "Reduced by 9500.000000, since earlier payment lowers the contractor''s own financing cost.", "As a note in the report that leaves the evaluated cost unchanged, because payment terms carry no price.", "As a priced deviation of 9500.000000, added to WS2''s evaluated cost."]'::jsonb, 3, 'The engine''s reason is "deviation payment-terms: asks for payment in 30 days where the conditions give 60; priced at the interest on the earlier payment (9500)". A minor deviation is quantified in money and added (Public Procurement Act 2007 s.31(14)). A major deviation reaches the engine only as a stated rejection reason, and a priced deviation is added to the cost.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 6, 'WS5 finishes in 9 weeks against a minimum of 6, at ratePerWeek 0.005. What completion-time adjustment does the engine add?', '["12741.000000, that is 0.005 x 3 x 849400", "8674.000000, the adjustment for two weeks beyond the minimum on WS2''s corrected price.", "0.005 x 9 x 849400, on all 9 weeks.", "0.000000, since 9 weeks is inside the maximum of 10 and so earns no charge."]'::jsonb, 0, 'The adjustment is ratePerWeek x the weeks beyond minWeeks x (corrected price less discount): 0.005 x 3 x 849400 = 12741, as the engine''s reason prints. 8674.000000 belongs to WS2. Only weeks beyond the minimum are charged, and the maximum of 10 marks rejection, with every week between 6 and 10 still charged.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 7, 'What price does the engine multiply to find the completion-time adjustment?', '["Whatever total the bidder wrote, before any arithmetic correction.", "The corrected price less the discount, a base the engine names as its convention.", "The corrected price before the discount, so a discount leaves the charge unchanged.", "One common base for all, the lowest evaluated cost in the tender."]'::jsonb, 1, 'The engine''s schedule basis reads "ratePerWeek 0.005 of (corrected price - discount) for each week beyond 6". The Works SPD (September 2025) gives the rate and leaves the base open, so the engine states its choice. The quoted total would carry an arithmetic slip into the charge, and charging before the discount would bill time on money already given back.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 8, 'WS1 promises completion in 6 weeks, the minimum. What does the engine return for its schedule term?', '["A credit of 4590.000000 for finishing a week sooner than WS3.", "Four weeks of credit for beating the maximum of 10, deducted from its price.", "0.000000, with no credit for finishing early.", "A charge of 0.005 on the first week."]'::jsonb, 2, 'The engine''s reason is "completion in 6 weeks is not beyond the minimum 6 weeks; no adjustment and no credit for earlier completion". The minimum is the fastest completion the company values, so no bid earns a credit for speed, against WS3 or against the maximum, and no week up to the minimum is charged.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 9, 'Under the well services schedule, minWeeks 6 and maxWeeks 10, a bid offers completion in 11 weeks. What does the engine do?', '["Charging 0.005 of the price for each of the 5 weeks beyond the minimum, it ranks the bid.", "A refusal naming schedule.maxWeeks, because a bid lies outside the stated band.", "It excludes the bid at the commercial stage and names the reason.", "It caps the bid at 10 weeks and charges the four weeks between 6 and 10."]'::jsonb, 2, 'The engine''s schedule basis says beyond 10 weeks the bid is rejected, so the bid leaves at the commercial stage as an exclusion with its reason, a result: "offers completion in 11 weeks, beyond the maximum 10 weeks; the bid is nonresponsive". The charge applies only to bids inside the band, a bid''s weeks are never capped, and a refusal is kept for bad inputs such as maxWeeks below minWeeks.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 10, 'Which bid holds the lowest evaluated cost of the well services tender, with omissions at the average and the fixture''s schedule?', '["WS5, at 862141.000000, with WS2 second at 885574.000000.", "WS2, since its corrected price of 867400.000000 carries no discount to deduct.", "WS1, once its discount is taken.", "WS3, because the average price of its nitrogen line is lower than any bid''s own."]'::jsonb, 0, 'Evaluated cost ascending, the engine returns WS5 862141.000000, WS2 885574.000000, WS1 928200.000000 and WS3 957990.000000. WS2 adds a deviation and 8674.000000 of schedule to 867400.000000, WS1''s discount leaves it third, and WS3''s figure, with its nitrogen priced in, is the largest of the four.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 11, 'WS3 quotes 918000.000000 and finishes in 7 weeks. How does its evaluated cost of 957990.000000 build up?', '["918000.000000 plus 35400.000000 plus 9500.000000 for a deviation on its payment terms.", "943200.000000 less its discount plus the nitrogen average of 35400.000000.", "918000.000000 plus 4590.000000 and a correction of 18000.000000 on ct-spread.", "918000.000000 plus 35400.000000 for the nitrogen omission plus 4590.000000 for one week beyond the minimum."]'::jsonb, 3, 'Each row of the engine''s table is the sum of its terms: WS3 has no correction, no discount and no deviation, so 918000.000000 + 35400.000000 + 4590.000000 = 957990.000000. The payment-terms deviation is WS2''s, 943200.000000 and the discount are WS1''s, and WS3''s correction is 0.000000.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 12, 'WS1 is given "omitted": ["mob"] while its bill still prices mob. What comes back?', '["An evaluated cost with mob counted twice, once as priced and once at the average.", "A refusal: \"bids[0].omitted lists ''mob'', which the bid also prices\".", "An evaluated cost with WS1''s own mob price removed and the average added in its place.", "A result that ignores the omitted list, since the bill line shows mob was priced."]'::jsonb, 1, 'An item cannot be both omitted and priced, and the engine refuses the call in its own words. It does not count the item twice, does not replace the bidder''s own price with an average, and does not quietly ignore the contradiction.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 13, 'No responsive bid other than WS3 prices nitrogen, and no best estimate is stated. What does the engine return?', '["A refusal: \"bestEstimates.nitrogen is required: bid WS3 omits item nitrogen and no other responsive bid prices it\".", "An omission of 0.000000, since no price exists to average and WS3 carries the risk of the item.", "WS4''s nitrogen price, the only other one quoted, used although its envelope was never opened.", "WS3 excluded at the commercial stage as a bid that failed to price every line of the bill."]'::jsonb, 0, 'The omission basis says the average of the other responsive bids, else the Employer''s best estimate. With neither, the engine refuses by name and asks for bestEstimates.nitrogen. It prices nothing at zero and does not reach into a failed bid''s prices, and an omission is no ground for exclusion.'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 14, 'A bid is given the rejection reason "major deviation: refuses the liability clause". What does the engine do with it?', '["Pricing the deviation at the bid''s discount, it ranks the bid with the others.", "The bid''s evaluated cost is set to the largest in the tender and it stays ranked.", "It asks for a price, refusing the call until the deviation carries an amount.", "Exclusion at the commercial stage, carrying the stated reason word for word."]'::jsonb, 3, 'A major deviation rejects a bid (Public Procurement Act 2007 s.31(7)) and reaches the engine as a stated rejection reason; the bid is excluded at the commercial stage with the reason given, and it is no longer responsive. Nothing prices it, no cost is imposed, and a stated reason is accepted as given (only an empty one is refused).'),
  ('procurement', 'beginner', 'module', 'm04-evaluated-cost', 15, 'What does WS5''s evaluated cost of 862141.000000 tell the company?', '["What the job will cost, since every correction and adjustment has already been made.", "That WS5 ranks first on cost under the stated rules; it is no forecast of the job''s cost.", "The sum the company will pay WS5 if the contract is awarded to it on these terms.", "The lowest total quoted in the tender, before any correction or adjustment of the bills."]'::jsonb, 1, 'An evaluated cost ranks bids under stated rules, with omissions at the average and the stated schedule, and is not a forecast of what the job will cost. Its completion-time adjustment of 12741.000000 is a term the stated schedule adds for the comparison, so the figure is no contract sum either, and the lowest quoted total was WS4''s, whose envelope stayed sealed.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 1, 'With Cmin 862141.000000, what commercial score does the lowest-ratio method give WS2, whose evaluated cost is 885574.000000?', '["88.235294, the ratio of WS2''s technical percentage to the highest one.", "97.353920, that is 100 x 862141 / 885574", "100.000000, as for WS5.", "90.970882, WS2''s rank-three figure."]'::jsonb, 1, 'The engine''s basis is Sc = 100 x Cmin / C with Cmin = 862141, so WS2 scores 97.353920. 88.235294 is WS2''s St, 100.000000 goes only to the lowest evaluated cost (WS5), and 90.970882 is WS2''s combined score B, which weighs St and Sc together.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 2, 'WS1''s technical percentage is 82.500000. What relative technical score St does the engine give it?', '["82.500000, as the relative method uses the percentage just as it was scored.", "330.000000, WS1''s weighted points, which the relative method carries forward.", "92.883107, WS1''s Sc.", "97.058824, measured against Thigh 85"]'::jsonb, 3, 'St = 100 x T / Thigh with Thigh = 85, WS3''s percentage, so WS1 scores 100 x 82.500000 / 85 = 97.058824. Using T as scored is the absolute method, weighted points never enter the combined score, and 92.883107 is WS1''s commercial score Sc.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 3, 'At technical weight 0.7, with lowest-ratio pricing and relative technical scoring, which bid is most advantageous?', '["WS3, at 96.998434", "WS5, which holds the lowest evaluated cost and so the commercial score of 100.000000.", "WS1, whose 95.806109 is the top combined score once its discount is taken into account.", "WS2, since its commercial score of 97.353920 is the best of any bid that scores below 100."]'::jsonb, 0, 'The engine ranks WS3 96.998434, WS1 95.806109, WS2 90.970882, WS5 87.647059. WS3 has the best technical proposal, St 100, and at a weight of 0.7 that lead outweighs its commercial score of 89.994781. WS5 ranks fourth despite Sc 100, and WS1''s figure is below WS3''s.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 4, 'Where does WS5, the bid with the lowest evaluated cost, rank on the combined score at technical weight 0.7?', '["First, since the combined score gives the lowest evaluated cost first place.", "Second, behind WS3, with a combined score of 95.806109.", "Fourth of four, at 87.647059", "Joint first with WS3, as both bids reach a score of 100 in one part."]'::jsonb, 2, 'WS5 scores Sc 100.000000 and St 82.352941, and 0.7 x 82.352941 + the rest x 100 gives 87.647059, the lowest of the four. 95.806109 belongs to WS1 in second place. Scoring 100 on one part is shared by WS3 (St) and WS5 (Sc) and gives neither a tie.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 5, 'Which bid sets Thigh in the well services combined score, and why can WS6 not set it?', '["WS3 at 85.000000; WS6 was never scored, so it is not among the bids ranked.", "WS6, whose strong proposal sets Thigh although its price envelope stays sealed.", "WS4, since Thigh is taken over every bid that the technical envelope scored.", "WS1, because Thigh is the percentage of the bid received first at the box."]'::jsonb, 0, 'Thigh is the highest technical percentage among the bids being ranked, the responsive ones, so the engine prints Thigh = 85 from WS3. WS6 failed a mandatory requirement and has no percentage at all, WS4''s price was never opened so it is not ranked, and receipt time plays no part in Thigh.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 6, 'The technical weight box of the combined score view is left empty. What comes back?', '["Ranks at a technical weight of 0.7, the figure the well services tender states in its settings.", "A refusal: \"technicalWeight must be a number from 0 to 1 (the technical share of the combined score); there is no default\".", "An even split of 0.5 between the technical and the commercial score of each bid, applied until a weight is typed.", "Ranks on the commercial score alone, as a missing technical weight is read as a weight of zero."]'::jsonb, 1, 'The technical weight has no default, so a combined score without one is refused in the engine''s own words. It borrows no weight from a fixture, assumes no even split, and never reads a blank as zero, because each of those would decide the award silently.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 7, 'In the envelope calculator''s combined score view, every bid carries a rejection reason. What does the engine return?', '["All the bids ranked, with the rejection reasons printed beside each row.", "A result naming the bid with the highest technical percentage as most advantageous.", "Zero combined scores, 0.000000 for each bid, with no bid named as most advantageous.", "The refusal \"bids has no bid left to score: every bid is rejected\", from rankTender."]'::jsonb, 3, 'The combined score needs at least one bid to rank, so rankTender refuses with the field bids and the message quoted, in its own words. It ranks no rejected bid, names no winner and prints no zero scores.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 8, 'What does the absolute technical method use as a bid''s technical score?', '["100 x T / Thigh, the percentage set against the highest one.", "Weighted points, the sum of weight x score, without dividing by maxScore.", "The technical percentage as scored, T itself", "Its margin over the pass mark, times 100."]'::jsonb, 2, 'The engine''s message states the two methods: ''relative'' (100 x T / Thigh) or ''absolute'' (T as scored). Dividing by the highest percentage is the relative method, weighted points are a separate figure the combined score does not use, and no method subtracts the pass mark.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 9, 'Every bid''s technical percentage is set to 0 with the relative method. What does the engine return?', '["An St of 100.000000 for every bid, since all of them tie for the top technical score.", "St 0.000000 for all, so cost decides.", "A switch to the absolute method.", "A refusal: Thigh is 0, so the relative score is undefined."]'::jsonb, 3, 'The engine''s message is "bids all score 0 technically, so Thigh is 0 and the ''relative'' technical score is undefined". Dividing by a Thigh of zero has no meaning, so the engine gives no St at all, and it never changes a method it was given.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 10, 'Why does a bid with an evaluated cost of 0 draw a refusal in the combined score?', '["Sc = 100 x Cmin / C has no meaning when C is zero, so the cost must be above 0.", "The engine reads a cost of 0 as a missing price and prices it at the average of the others.", "A cost of 0 gives every other bid Sc 100.000000.", "A bid of 0 is read as withdrawn."]'::jsonb, 0, 'The commercial score divides by each bid''s evaluated cost, so the engine refuses with "bids[0].evaluatedCost must be a finite number above 0". It does not price the bid at an average, which is the omission rule for a single item, and it makes no guess about withdrawal.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 11, 'The Guidance''s Figures X to XII print Company D''s combined score as 98.34. What does the engine return for D?', '["98.34 exactly, the printed figure, which the engine reproduces to the last digit.", "98.333333, exact; the Guidance prints two decimals", "80.000000, the technical part alone, since D wins on its technical score.", "91.666667, D''s commercial score, which the Guidance prints as 91.7 in its table."]'::jsonb, 1, 'At the technical weight of 0.8 that the World Bank Guidance (February 2025) states, the engine returns D''s B as 98.333333, within 0.01 of the printed 98.34; two figures that look close are still different, and the course quotes each as printed. 80.000000 is 0.8 x St, 91.666667 is Sc, and the ranking D, C, B, A agrees with the Guidance.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 12, 'In the Guidance''s Figures X to XII, Company C scores Sc 100.000000. Why is D most advantageous at technical weight 0.8?', '["C is rejected after examination, leaving D ahead of the rest.", "D has the lower evaluated cost once corrected.", "D''s technical lead outweighs C''s cost lead at that weight.", "A tie goes to D, received first."]'::jsonb, 2, 'At the 0.8 that the World Bank Guidance (February 2025) states, the technical score carries most of the weight: D''s 0.8 x St is 80.000000 against C''s 68.333333, and C''s Sc of 100.000000 against D''s 91.666667 cannot close that gap, so D scores 98.333333 and C 88.333333. The excluded company is E, C holds the lowest cost, and there is no tie.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 13, 'The Guidance''s Annex 3 states a technical weight of 0.4. What does the engine return for Company A?', '["St 100.000000, Sc 90.625000 and B 94.375000, the Guidance printing 94.37", "St 79.166667, Sc 100.000000 and B 91.666667, the winning figures for the bid.", "St 100.000000 and B 94.37, since the printed figure is the engine''s own.", "B 240.000000, A''s weighted points, which the Annex uses as its combined score."]'::jsonb, 0, 'The engine returns A at St 100.000000, Sc 90.625000, B 94.375000, and B at St 79.166667, Sc 100.000000, B 91.666667, so A wins on both. The World Bank Guidance (February 2025) prints 94.37, two decimals of the engine''s figure with the third dropped. 240.000000 is A''s weighted points and plays no part in B.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 14, 'On the well services bids, what happens to the most advantageous bid if the technical weight is set to 0, and if it is set to 1?', '["At 0 it is WS3 and at 1 it is WS5, since the weight is the share given to price.", "It is WS3 at every weight, because WS3 holds the best technical proposal.", "Both are refused as out of range.", "At 0 it is WS5 (Sc alone); at 1 it is WS3 (St alone)."]'::jsonb, 3, 'B = technical weight x St + the rest x Sc, so a weight of 0 ranks on Sc alone and WS5, with the lowest evaluated cost, is most advantageous; a weight of 1 ranks on St alone and WS3 leads (engine run on the four responsive bids). The input is the technical share, and the engine accepts any weight from 0 to 1.'),
  ('procurement', 'beginner', 'module', 'm05-the-combined-score', 15, 'The Works SPD (September 2025) writes the combined evaluation as B = Clow / C x X x 100 + T / Thigh x (1 - X) x 100. What does X stand for, and what does the engine take as its input?', '["The technical weight, which the engine takes directly as its own input.", "X is the weight on price; the engine takes the technical weight and gives the rest to Sc.", "A fraction for the pass mark, which the engine reads from the technical envelope.", "Cmin, the lowest evaluated cost, as the engine names it in its basis."]'::jsonb, 1, 'In the SPD''s formula X multiplies the price term Clow / C, so it is the price weight. The engine''s input is technicalWeight, the technical share, and the commercial score takes 1 minus it, which is why its basis at 0.7 reads B = 0.7 x St plus the rest x Sc. The pass mark and Cmin are separate quantities.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 1, 'The whole well services tender runs in one call with a combined award at the fixture''s settings. Which award and reason does the engine return?', '["WS5, with the reason that it holds the lowest evaluated cost of the four bids ranked.", "WS1, as it finishes early with a discount.", "WS3, with the reason \"WS3 has the highest combined score\"", "No award, since two bids lead on two figures."]'::jsonb, 2, 'Under award combined at technical weight 0.7, lowest-ratio and relative, the engine awards WS3 with the reason quoted, its own words. WS5 wins only under a lowest-cost award, WS1 ranks second on the combined score, and two bids leading on two different figures is an ordinary outcome that still yields one award.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 2, 'The award basis of the same tender is changed from combined to lowest-cost. What does the engine award?', '["WS5, because \"WS5 has the lowest evaluated cost\"", "WS4, whose quoted total of 763200.000000 is the lowest of the six bids received by the company.", "WS3 still, since the award follows the technical envelope whatever basis the tender names.", "WS2, whose quoted total is level with WS5''s and which was received on an earlier day."]'::jsonb, 0, 'Under a lowest-cost award the engine names the bid with the lowest evaluated cost, WS5 at 862141.000000. WS4''s price was never opened, the basis decides the award so WS3 does not stay, and WS2''s corrected price and deviation leave it second on evaluated cost.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 3, 'Why do the combined award and the lowest-cost award name different bids on the well services tender?', '["The combined award adds a technical bonus to WS3''s price, so its evaluated cost becomes the lowest.", "The lowest-cost award reads WS5''s price as quoted.", "One award is wrong and the engine flags it.", "The combined score weighs the technical percentage at 0.7, and WS3 has the best one."]'::jsonb, 3, 'WS3 carries the highest technical percentage and the fourth-lowest evaluated cost; WS5 the lowest evaluated cost and the lowest technical percentage of the four. Weighing quality at 0.7 makes WS3 most advantageous; weighing cost alone picks WS5. Neither award is wrong: each answers the question its basis asks, and both use the corrected prices.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 4, 'In what order does the engine break a tie on the combined score?', '["Higher technical percentage, then lower evaluated cost, then a fresh price from the bidders tied.", "Lower evaluated cost, then earlier receipt, then bidder id.", "Earlier receipt, then lower quoted total, then the committee''s vote on the tied bids.", "Bidder id first, then receipt."]'::jsonb, 1, 'The engine''s ranking basis reads "combined score descending; ties at 12 significant digits go to the lower evaluated cost, then the earlier receipt, then the bidder id". No text read states a tie-break, so this order is the engine''s stated convention; it asks for no fresh price, holds no vote and uses the quoted total nowhere.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 5, 'Stated as a test, T1, T2 and T3 score 100.000000 each; T1 and T2 were received at 09:00:00 and T3 at 10:00:00. What does tieBrokenBy show for T2 and T3?', '["T2 earlier receipt and T3 bidder id, since T2 arrived in the same second as T1.", "Lower evaluated cost for both, because it is the first key of the tie-break order.", "Null for both, as three identical combined scores leave the order undecided.", "T2 bidder id; T3 earlier receipt"]'::jsonb, 3, 'The three share an evaluated cost of 500000, so the first key cannot separate them. T1 and T2 arrive in the same second, so the bidder id orders T2 after T1; T3 arrived later, so earlier receipt orders it third. tieBrokenBy is null only on the first row.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 6, 'Stated as a test, U2 has T 100 and C 1000 and U1 has T 50 and C 500, at technical weight 0.5. Both score 75.000000. Which ranks first?', '["U2, because it holds the higher technical percentage of the two tied bids.", "Neither; the engine returns both at rank 1 and leaves the award open.", "U1, broken by \"lower evaluated cost\"", "U2, since the bid named second in the input is ranked ahead on a tie."]'::jsonb, 2, 'When the combined scores tie, the first key of the tie-break is the lower evaluated cost, so U1 at 500 ranks ahead of U2 at 1000. The technical percentage is not a tie-break key, every ranking is strict, and input order plays no part.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 7, 'At how many significant digits does the engine treat two figures as tied?', '["Twelve, an engine convention (TIE_DIGITS 12).", "Six, the number of decimals every figure in the course is printed to.", "Two, as the Guidance (February 2025) prints.", "Every digit of the double, so only bit-for-bit equal figures tie."]'::jsonb, 0, 'TIE_DIGITS is 12: two routes to the same score can land a hair apart in the last binary digits, and twelve significant digits treat such hairs as equal while keeping every difference a person could print. Six decimals is only the printing precision, so figures printed alike at six decimals are not for that reason tied.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 8, 'Which bids does the whole well services call list as excluded, and at what stage?', '["WS4 at the technical stage and WS6 at the commercial stage for a missing signature.", "WS4, WS6 and WS5, as WS5 sits on the pass mark and is excluded with the other two.", "WS6 alone, since WS4 was scored and stays on the ranking of the combined score.", "WS4 and WS6, both at the technical stage."]'::jsonb, 3, 'The engine lists WS4 (technical score 65 below the pass mark 70) and WS6 (failed signed-bid-form), each at the technical stage, with its reason verbatim. A mandatory failure is found in the technical envelope, WS5 at 70.000000 passes, and a bid below the pass mark is excluded even though it was scored.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 9, 'How should an evaluation report describe what happened to WS4 and WS6?', '["Refusals, because the engine would not evaluate either bid and returned an error.", "As exclusions: results the engine returned, each with its stage and its reason in quotation marks.", "Input errors in the two bids, to be corrected before the tender is run again.", "As bids withdrawn by their own bidders before the envelopes were opened."]'::jsonb, 1, 'An exclusion is a result: the engine evaluated both bids and returned them excluded with the reason beside each. A refusal returns no result for a bad input, nothing in either bid is an input error, and neither bidder withdrew.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 10, 'A receipt time is typed as 2027-05-01T09:00:00 with no zone letter. What does the engine return?', '["A refusal: \"bids[0].receivedAt must be a UTC time ''YYYY-MM-DDTHH:MM:SSZ''\".", "UTC is assumed, since the tender box keeps UTC and the Z adds nothing to it.", "Local time, converted with a note on the offset it assumed.", "The bid ranked last on any tie."]'::jsonb, 0, 'A tie can turn on the receipt time, so the engine takes a UTC time only in the stated form and refuses anything else by name, in the words quoted. It assumes no zone, converts nothing, and penalises no bid for a malformed time.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 11, 'When bids are ranked by evaluated cost, what orders them and what breaks a tie?', '["Technical percentage descending, with the lower evaluated cost breaking any tie between two bids.", "Quoted total ascending, as priced.", "Ascending evaluated cost, and at a tie the bid received first, then its id.", "Evaluated cost descending, the dearest first, with any tie left for the committee to settle."]'::jsonb, 2, 'The engine''s ranking basis for evaluated cost reads: evaluated cost ascending; ties at 12 significant digits go to the earlier receipt, then the bidder id. A cost ranking cannot break a tie on the cost it is ranking by, quoted totals are never ranked, and no tie is left undecided. On the well services tender no two evaluated costs tie.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 12, 'Which text does the engine cite as the source of the combined award?', '["Public Procurement Act 2007 s.24(3), on the lowest evaluated responsive bid, as its source.", "Figure IX of the Guidance on Evaluating Bids and Proposals (February 2025), on weighted points.", "The Regulations (Seventh Edition, September 2025), para 6.29 on the two envelopes.", "The Works SPD, two-envelope (Sep 2025), Section III: B = Clow / C x X x 100 + T / Thigh x (1 - X) x 100."]'::jsonb, 3, 'The engine''s award source for the combined basis is the World Bank SPD Request for Bids, Works, two-envelope (Sep 2025) Section III with the formula quoted. s.24(3) is the lowest evaluated responsive bid, Figure IX prints weighted points, and para 6.29 is the source of the technical stage.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 13, 'At which stage can a bid be excluded for completion beyond the maximum weeks or a stated rejection reason?', '["The technical stage, together with bids that fail the pass mark or a requirement.", "The commercial stage, with the reason printed in the exclusions.", "The award stage, after ranking, when the most advantageous bid is checked.", "No stage; both are charged as adjustments in the evaluated cost."]'::jsonb, 1, 'A stated rejection reason, such as a major deviation, and completion beyond maxWeeks each exclude a bid at the commercial stage, and the exclusion carries its stage. The technical stage covers mandatory requirements and the pass mark, the award stage excludes nobody, and neither case is priced as an adjustment.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 14, 'The award line is deleted from the whole tender call. What does the engine return?', '["A refusal: \"award must be ''lowest-cost'' or ''combined''; there is no default\".", "A combined award, the basis the well services tender states in its settings.", "A lowest-cost award, the basis that the Public Procurement Act 2007 prefers.", "Both awards side by side, leaving the committee to choose one of the two for the contract."]'::jsonb, 0, 'The award basis has no default, and evaluateTender refuses the call by name in the words quoted. It borrows no basis from a fixture or a statute and prints no pair of awards, since choosing a basis is the tender''s decision, stated before any bid is opened.'),
  ('procurement', 'beginner', 'module', 'm06-reading-an-award', 15, 'WS3 wins the combined award. Which statement about WS3 fits the course''s meaning of most advantageous?', '["WS5 is most advantageous, because its evaluated cost of 862141.000000 is the lowest of the four.", "WS6 is most advantageous on paper, as its scores are the strongest of the six bids.", "WS3 is most advantageous at 96.998434 under technical weight 0.7, lowest-ratio and relative.", "WS3 is most advantageous in every sense, whatever technical weight is chosen."]'::jsonb, 2, 'Most advantageous names the highest combined score under a stated technical weight and stated methods. WS5 holds the lowest evaluated cost, which is a different term; WS6 was never scored; and WS3''s lead depends on the weight, since at a weight of 0 the most advantageous bid is WS5.'),
  ('procurement', 'beginner', 'final', null, 1, 'A bill line carries a key named unitPrice, which the engine does not read. What happens?', '["The unknown key is dropped without a word and the line is priced from its unitRate as usual.", "Its value replaces the unit rate, since unitPrice is read as another name for it.", "The call is refused, naming the key, its path and the keys a bill line accepts.", "The line is excluded from the bill."]'::jsonb, 2, 'The engine refuses any input key a function does not read, at every level, with the message "bids[0].lines[0].unitPrice is not an accepted key; the accepted keys of bids[0].lines[0] are id, quantity, unitRate, quotedAmount, decimalMisplaced". A misspelt key never silently drops a term, so nothing is ignored, substituted or excluded.'),
  ('procurement', 'beginner', 'final', null, 2, 'A result comes back from the envelope calculator. What does it hold beside its figures?', '["A basis block naming the rule applied and where it comes from, so the working can be printed.", "A statistical band around each figure, drawn from the spread of the bids received.", "Signatures from the tender committee, recorded when the result is approved.", "Notes on the inputs it changed to make the call run without a refusal."]'::jsonb, 0, 'Every result carries a basis block naming the rule it applied and its source, which the envelope calculator prints in the engine''s words. The engine returns no statistical band here, records no signature, and changes no input: a bad input is refused by name.'),
  ('procurement', 'beginner', 'final', null, 3, 'Which of these does the engine leave uncomputed?', '["Arithmetic correction of each bill line against its quantity and unit rate.", "Completion-time adjustment for weeks beyond the stated minimum.", "The ranking of the bids, with its stated tie-break of three keys.", "A negotiation or best and final offer."]'::jsonb, 3, 'The engine computes no negotiation or best and final offer, splits no tender into lots and compares no amount in words against figures. Correcting bills, adjusting for completion time and ranking with a stated tie-break are among the things it does compute.'),
  ('procurement', 'beginner', 'final', null, 4, 'How does the course name the Nigeria Public Procurement Act 2007 with its edition?', '["The Seventh Edition, September 2025, read with the World Bank Regulations it adopts.", "Act No. 14, Official Gazette No. 65, Vol. 94, 19 June 2007, read on 2026-09-26.", "Act No. 2, commenced 22 April 2010, as enacted and read on the same date.", "The February 2025 edition, published beside the Goods two-envelope SPD."]'::jsonb, 1, 'The sources table gives the Act as Act No. 14 in Official Gazette No. 65, Vol. 94, 19 June 2007, read on 2026-09-26. The Seventh Edition is the World Bank Regulations, Act No. 2 of 2010 is a different statute the course reads at a later tier, and February 2025 is the Guidance and the Goods SPD.'),
  ('procurement', 'beginner', 'final', null, 5, 'In which edition does the course read the World Bank Standard Procurement Document, Request for Bids, Goods, two-envelope?', '["September 2025, the same edition as the Works document the engine cites.", "February 2025, for ITB 34.1 and ITB 35.1 for goods.", "Second Edition, July 2016, read for its worked examples in Annex I.", "The Nigerian gazette edition."]'::jsonb, 1, 'The sources table lists the Goods two-envelope SPD at February 2025, read for ITB 34.1 and ITB 35.1, and the Works two-envelope SPD at September 2025. The gazette reference belongs to the Public Procurement Act 2007, and the 2016 edition belongs to a guidance the course reads at a later tier.'),
  ('procurement', 'beginner', 'final', null, 6, 'What work does tender EK-11/WS/2027-01 buy?', '["Casing, wellhead valves, cement and baryte for two Ekene infill wells, delivered to the supply base.", "A land rig for a two-well drilling programme.", "Seismic acquisition over block EK-11.", "A coiled tubing cleanout and matrix acid stimulation of Ekene-3 and Ekene-5."]'::jsonb, 3, 'The well services tender is the synthetic coiled tubing cleanout and 15% HCl matrix acid job on Ekene-3 and Ekene-5, with six bill items from mob to demob. Casing, valves, cement and baryte are the materials tender EK-11/MS/2027-02, and neither Ekene tender buys a rig or seismic work.'),
  ('procurement', 'beginner', 'final', null, 7, 'How many bids does the materials tender receive, and on what basis is it awarded?', '["Five, MS1 to MS5, with the award to the lowest evaluated cost.", "Six, MS1 to MS6, awarded on the combined score at technical weight 0.7.", "Four, as MS5 withdrew.", "Five, awarded to the highest technical percentage, which is MS3 at 90.000000."]'::jsonb, 0, 'The materials tender has five bids and states the award as the lowest evaluated cost, with a pass mark of 60. The combined award at 0.7 is the well services tender''s, MS5 is a bid that fails the pass mark and never withdrew, and a technical percentage alone awards nothing.'),
  ('procurement', 'beginner', 'final', null, 8, 'MS3 scores 4, 3 and 3 on specification (weight 60), delivery (25) and after-sales (15), each out of 4. What technical percentage does the engine return?', '["360.000000, which is the weighted points total that MS3 earns on these scores.", "100.000000, since a full score on specification carries the whole technical envelope.", "90.000000, the top figure of the materials tender", "75.000000"]'::jsonb, 2, 'The terms are 60 x 4 / 4 = 60.000000, 25 x 3 / 4 = 18.750000 and 15 x 3 / 4 = 11.250000, which sum to 90.000000. 360.000000 is MS3''s weighted points, a full score on one criterion earns only that criterion''s weight, and 75.000000 is MS1''s percentage at 3, 3 and 3.'),
  ('procurement', 'beginner', 'final', null, 9, 'Which well services bid returns the same technical percentage and weighted points as MS1 on the materials tender?', '["WS1, at 82.500000 and 330.000000, the nearest of the scored bids.", "WS5, since both bids sit on or near the pass mark of their tenders.", "No bid can, as the two tenders use different weights and criteria.", "WS2, at 75.000000 and 300.000000."]'::jsonb, 3, 'MS1 returns 75.000000 and 300.000000, and so does WS2, which scores 3 on all five well services criteria. Different weights give the same figures when every score is 3 of 4 on criteria whose weights sum to 100. WS1 returns 82.500000 and 330.000000, and WS5 70.000000 and 280.000000.'),
  ('procurement', 'beginner', 'final', null, 10, 'A pass mark of 101 is entered in the technical envelope. What comes back?', '["The same refusal as a missing pass mark: a number from 0 to 100, with no default.", "Every bid fails the pass mark, and each is returned with the status fail-pass-mark.", "The pass mark is capped at 100, so only a bid with full marks everywhere passes.", "The pass mark is read as 101 weighted points and compared with each bid''s points."]'::jsonb, 0, 'The engine''s message for both a missing pass mark and one of 101 is "passMark must be a number from 0 to 100 (a percentage of the maximum technical score); there is no default". The pass mark is a percentage, so a value outside 0 to 100 is refused and is neither capped nor reinterpreted, and no bid is scored against it.'),
  ('procurement', 'beginner', 'final', null, 11, 'A criterion is entered with a maxScore of 0. What does the engine return?', '["A term of zero for that criterion on every bid, whatever each bid scores on it.", "The criterion dropped from the tender and its weight shared among the others.", "A refusal: \"criteria[0].maxScore must be a finite number above 0\".", "A maxScore of 1 put in its place."]'::jsonb, 2, 'Each term divides by the criterion''s maxScore, which has no meaning at zero, so the engine refuses the criterion by name in the words quoted. It computes no zero term, drops no criterion and supplies no substitute scale.'),
  ('procurement', 'beginner', 'final', null, 12, 'A bid''s scores include a score for price, which is not a criterion of the tender. What does the engine do?', '["Price is scored with the weight left over once the named criteria are counted.", "It refuses: price is not a criterion id, and the message lists the ids it accepts.", "The price score is ignored and the bid scored on the five criteria it knows.", "Moved into the commercial envelope, the price score is used at the next stage."]'::jsonb, 1, 'The engine''s message is "bids[0].scores.price is not a criterion id; the accepted keys of bids[0].scores are the criterion ids methodology, personnel, equipment, hse, schedule". A key that is an id is checked against the ids the call carries, so nothing is scored, ignored or moved.'),
  ('procurement', 'beginner', 'final', null, 13, 'The technical envelope''s basis carries a source string. Which texts does it cite?', '["Para 6.29 of the World Bank Regulations (7th ed.) and s.51(2) of the Public Procurement Act 2007.", "ITB 35.1(a) and (b) of the Works SPD, two-envelope (Sep 2025), with s.31(4) of the Public Procurement Act 2007.", "Annex X para 3.6 of the Regulations (7th ed.) with s.24(3) and s.33(1) of the Public Procurement Act 2007.", "Figure IX and Annex 2 of the Guidance on Evaluating Bids and Proposals (February 2025)."]'::jsonb, 0, 'The engine''s basis.source for the technical envelope reads "World Bank Procurement Regulations (7th ed.) para 6.29; Nigeria Public Procurement Act 2007 s.51(2)". ITB 35.1 is the arithmetic rule, Annex X para 3.6 with s.24(3) belongs to the evaluated cost, and the Guidance''s examples are recomputed as checks.'),
  ('procurement', 'beginner', 'final', null, 14, 'WS2 scores 3 of 4 on every well services criterion. What technical percentage results?', '["300.000000, since the percentage is the sum of weight x score with no division.", "70.000000, which is WS5''s percentage, as the two bids share the same quoted total.", "88.235294, its percentage once WS3''s score of 85.000000 is set as the top of the scale.", "75.000000, three quarters of each weight"]'::jsonb, 3, 'Each term is weight x 3 / 4, so the five terms are three quarters of 30, 25, 20, 15 and 10, summing to 75.000000. 300.000000 is WS2''s weighted points, WS5''s 70.000000 comes from its own scores whatever its price, and 88.235294 is WS2''s relative technical score St in the combined score.'),
  ('procurement', 'beginner', 'final', null, 15, 'Across all six well services bills, how many lines does the engine correct, and by which rules?', '["One, WS2''s ct-spread by unit-rate-prevails, as WS5''s flagged acid line is left alone.", "Two: WS2''s ct-spread by unit-rate-prevails and WS5''s acid by total-governs.", "Six, one on each bill.", "Two, WS2''s ct-spread and WS5''s acid, both by the rule unit-rate-prevails."]'::jsonb, 1, 'The correction table shows WS2 with 1 line corrected by unit-rate-prevails and WS5 with 1 line corrected by total-governs; every other line of every bid passes the test. WS5''s line is corrected, its unit rate going to 1380, even though its amount and total stand.'),
  ('procurement', 'beginner', 'final', null, 16, 'correctArithmetic run on WS6''s bill returns a correction of 0.000000 on 1004400.000000. Does that bill reach an evaluated cost?', '["Yes, a bill with no correction goes straight on to the evaluated cost.", "Only as a reference price for items other bids omit.", "Only if the committee waives the signed-bid-form requirement.", "No; WS6 failed signed-bid-form, so its commercial envelope is never opened."]'::jsonb, 3, 'The arithmetic view corrects any bill it is given, but in the tender the stages decide: WS6 fails a mandatory requirement at the technical stage, so its price is never opened, it prices no one''s omission, and a clean bill is no ground to revisit a failed requirement.'),
  ('procurement', 'beginner', 'final', null, 17, 'A bill line gives decimalMisplaced as the text "yes". What does the engine return?', '["A refusal: \"lines[0].decimalMisplaced must be true or false when given\".", "Read as true, since any text that is not empty is taken to mean yes to the flag.", "False, with no message.", "The line left out of the total."]'::jsonb, 0, 'The flag is a stated judgement and must be true or false, so the engine refuses text by name in the words quoted. It reads no text as true or false and excludes no line; a line with no flag given is simply checked by the ordinary rule.'),
  ('procurement', 'beginner', 'final', null, 18, 'A bill line carries a negative unit rate, minus 27000. What does the engine do?', '["It takes the size of the rate, 27000, and corrects the line from that figure.", "A credit, deducted from the total.", "Refused: no unit rate may sit below 0.", "A zero rate, with the amount governing."]'::jsonb, 2, 'A negative unit rate is refused in the engine''s words: "lines[0].unitRate must be a finite number at or above 0". The engine changes no sign, books no credit, and sets no rate on its own, since each would be a correction nobody stated.'),
  ('procurement', 'beginner', 'final', null, 19, 'A bill line is typed with no id. Why does the engine refuse it?', '["Because the engine prices each line by looking its id up in a stored list of rates for the tender.", "Every correction names its line, so each line needs a non-empty id.", "The id sets the order of the sum.", "An unnamed line is read as a total."]'::jsonb, 1, 'The engine''s message is "lines[0].id must be a non-empty string": each corrected line is reported by its id, so a line with none could not be named in the reasons. The engine holds no list of rates, adds the lines in any order to the same corrected total, and a stated total is its own input, quotedTotal.'),
  ('procurement', 'beginner', 'final', null, 20, 'The engine''s reason for WS2''s ct-spread line says the gap is more than 0.005. What is that 0.005?', '["The ratePerWeek of the well services schedule, which also reads 0.005.", "A fraction of the line amount, so a gap under half a percent is ignored.", "A share of WS2''s quoted total.", "The default tolerance, used because the call stated none."]'::jsonb, 3, 'The arithmetic basis reads "a line is in discrepancy when |quantity x unit rate - quoted amount| > 0.005" at the default tolerance, half a cent in money. The schedule''s ratePerWeek happens to print as 0.005 too, but it is a different setting; the tolerance is an amount of money, and WS2''s correction is 18000.000000.'),
  ('procurement', 'beginner', 'final', null, 21, 'A bid''s bill is sent to the arithmetic correction with an empty list of lines. What comes back?', '["A refusal: \"lines must be an array of at least 1 entry\".", "A corrected total of 0.000000 and a correction equal to the quoted total.", "The quoted total accepted as it stands, since there are no lines to check.", "Every item treated as omitted."]'::jsonb, 0, 'The engine checks that a bill is a bill before any arithmetic, so an empty list of lines is refused by name. It builds no zero total, accepts no unchecked total, and does not turn a missing bill into omissions.'),
  ('procurement', 'beginner', 'final', null, 22, 'WS2 finishes in 8 weeks. Which base does its completion adjustment of 8674.000000 use?', '["849400.000000, its quoted total, since the rate is applied to the price as bid.", "867400.000000, its corrected price, with no discount to deduct", "885574.000000, its evaluated cost.", "862141.000000, one shared base."]'::jsonb, 1, 'The adjustment is 0.005 x 2 weeks x (corrected price less discount), and the engine''s reason prints 0.005 x 2 x 867400 = 8674. The quoted total would carry the arithmetic slip into the charge, the evaluated cost already contains the adjustment, and no common base is used.'),
  ('procurement', 'beginner', 'final', null, 23, 'How much does WS3''s one late week add to its evaluated cost?', '["0.005 x 2 x 918000, counting the week the job starts in.", "0.000000, as the minimum is only exceeded by a single week.", "4590.000000, one week at 0.005 of 918000", "12741.000000, the adjustment WS5 carries for its later finish."]'::jsonb, 2, 'One week beyond the minimum gives 0.005 x 1 x 918000 = 4590, as the engine''s reason prints. Only weeks beyond minWeeks count, every such week is charged, and 12741.000000 is WS5''s adjustment for 3 weeks.'),
  ('procurement', 'beginner', 'final', null, 24, 'Among the four passing well services bids, WS1 quotes the most. Where does it rank on evaluated cost?', '["Third, at 928200.000000, ahead of WS3.", "Fourth, since the ranking on evaluated cost keeps the order of the quoted totals.", "First, because its discount and a finish in 6 weeks leave it with no additions.", "Second, just behind WS5, as only WS5 has a smaller quoted total than WS1."]'::jsonb, 0, 'The engine ranks WS5 862141.000000, WS2 885574.000000, WS1 928200.000000 and WS3 957990.000000. WS1''s discount and its zero completion charge lift it above WS3, whose omission and week late add 35400.000000 and 4590.000000, but WS5 and WS2 stay below it.'),
  ('procurement', 'beginner', 'final', null, 25, 'What happens when the schedule''s ratePerWeek is typed as 2?', '["Adjustments at twice the price for each late week, which would decide every award at once.", "A rate of 2 percent, read as a percentage, applied to the corrected price less the discount.", "A rate capped at 1, so each late week adds the whole price to the evaluated cost.", "A refusal: the rate must be a fraction from 0 to 1 of the price for each week beyond minWeeks."]'::jsonb, 3, 'The engine''s message is "schedule.ratePerWeek must be a fraction from 0 to 1 of the price for each week beyond minWeeks". It computes nothing on an out-of-range rate, reinterprets no figure as a percentage, and caps nothing.'),
  ('procurement', 'beginner', 'final', null, 26, 'A schedule is stated but one bid gives no completion weeks. What happens?', '["The bid is charged for the maximum of 10 weeks, the worst case the tender allows, and ranked with the rest.", "The engine refuses, because every bid must give its completion weeks when a schedule is given.", "The bid is treated as finishing at the minimum of 6 weeks, so no completion charge is added to its cost.", "Excluded at the commercial stage for failing to state a completion time."]'::jsonb, 1, 'The engine''s message is "bids[0].completionWeeks must be a finite number at or above 0 when a schedule is given". It assumes neither the maximum nor the minimum, and a missing input is a refusal before the evaluation runs, so no exclusion is returned.'),
  ('procurement', 'beginner', 'final', null, 27, 'A learner types maxWeek for maxWeeks in the schedule. What comes back?', '["A schedule with no maximum at all, so that no bid is rejected at the commercial stage however late it offers to finish.", "The value read as maxWeeks, since the engine corrects a near miss in a key name and says so beside it.", "The refusal \"schedule.maxWeek is not an accepted key; the accepted keys of schedule are minWeeks, maxWeeks, ratePerWeek\".", "The whole schedule dropped without a word, with every completion adjustment in the tender returned as 0.000000."]'::jsonb, 2, 'An input key the function does not read is refused at whatever level it sits, with its path and the accepted keys, in the engine''s words. A misspelt optional key never silently drops a term, so the engine neither runs without a maximum, guesses the intended key, nor drops the schedule.'),
  ('procurement', 'beginner', 'final', null, 28, 'A best estimate is stated for mob, an item no bid omits. What does the engine return?', '["A refusal: mob is no item any bid omits, and nitrogen is the only accepted key.", "Stored for later use, in case a bid is found to omit mob afterwards.", "Added to every bid''s mob line as an Employer''s check on the price.", "Ignored, with nitrogen priced at the average of the three other bids."]'::jsonb, 0, 'The engine''s message is "bestEstimates.mob is not an item any bid omits; the accepted keys of bestEstimates are the omitted item ids nitrogen". A key that is an id is checked against the ids the call carries, so an estimate for an item nobody omits is neither stored, applied nor ignored.'),
  ('procurement', 'beginner', 'final', null, 29, 'Which paragraph of the World Bank Procurement Regulations (Seventh Edition, September 2025) does the engine cite first as the source of the evaluated cost?', '["Para 6.29, the paragraph that describes the two-envelope process itself.", "Para 5.69, the paragraph that sets out the Most Advantageous Bid award.", "ITB 34.1, the clause that prices an omitted item at the average of the others.", "Annex X para 3.6 of the Seventh Edition"]'::jsonb, 3, 'The engine''s basis.source for the evaluated cost begins "World Bank Procurement Regulations (7th ed.) Annex X para 3.6" and adds s.31(14), s.32(3), para 5.70, s.24(3) and s.33(1). Para 6.29 is cited for the technical stage, ITB 34.1 belongs to the Works SPD, and para 5.69 sets out the Most Advantageous Bid, which the evaluated cost basis does not cite.'),
  ('procurement', 'beginner', 'final', null, 30, 'Take WS1''s evaluated cost, 928200.000000, and the lowest, 862141.000000. What is WS1''s Sc?', '["97.058824, the ratio of WS1''s technical percentage to WS3''s.", "100.000000, since its discount makes WS1 the lowest bid on cost.", "92.883107, from 100 x 862141 / 928200", "95.806109, the combined figure that places WS1 second of the four."]'::jsonb, 2, 'Sc = 100 x Cmin / C with Cmin = 862141 gives WS1 92.883107. 97.058824 is WS1''s St, 100.000000 belongs to WS5 alone, and 95.806109 is WS1''s combined score B at technical weight 0.7.'),
  ('procurement', 'beginner', 'final', null, 31, 'WS3 has the largest evaluated cost of the four responsive bids, 957990.000000. What commercial score does it get?', '["0.000000, as the dearest bid is placed at the bottom of the commercial scale.", "89.994781, still near 90", "82.352941, which is the lowest commercial score that the ratio can give a bid.", "100.000000, since the combined score rescales each part to reach 100."]'::jsonb, 1, 'The lowest ratio gives 100 x 862141 / 957990 = 89.994781. It compresses cost differences, so the dearest bid still scores near 90; it sets no bottom at zero. 82.352941 is WS5''s St, and only the lowest evaluated cost scores 100 on price.'),
  ('procurement', 'beginner', 'final', null, 32, 'With Thigh 85.000000, what relative technical score does WS2 receive?', '["75.000000, the percentage as scored, since the relative method leaves it alone.", "97.353920, which is WS2''s figure once its evaluated cost is set against Cmin.", "90.970882, the combined score that ranks WS2 third at a weight of 0.7.", "88.235294, from 100 x 75 / 85"]'::jsonb, 3, 'St = 100 x T / Thigh gives WS2 100 x 75 / 85 = 88.235294. 75.000000 unchanged would be the absolute method, 97.353920 is WS2''s commercial score Sc, and 90.970882 is its combined score B.'),
  ('procurement', 'beginner', 'final', null, 33, 'Which commercial score does the engine return for Company B, where the Guidance prints 88?', '["88.000018, the engine''s exact figure", "84.266670, B''s combined score, printed as 84.26.", "66.666667, B''s weighted technical part at 0.8.", "100.000000, as for C."]'::jsonb, 0, 'Company B''s commercial score from the engine is 88.000018; Figures X to XII of the World Bank Guidance (February 2025) show 88, so the two print alike at that precision and remain two different figures. 84.266670 is B''s combined score, 66.666667 is its technical part at 0.8, and Sc 100.000000 belongs to C, the lowest cost of the four.'),
  ('procurement', 'beginner', 'final', null, 34, 'In the Guidance''s Annex 3, A has 240.000000 weighted points and B 190.000000. What St does B receive under relative scoring?', '["190.000000, as B''s points pass unchanged into the combined score.", "100.000000, since B has the lowest cost and scores 100 on price.", "79.166667, from 100 x 190 / 240", "91.666667, the combined score B reaches at technical weight 0.4."]'::jsonb, 2, 'In the World Bank Guidance (February 2025) example, relative scoring divides by the top bid: 100 x 190 / 240 = 79.166667, and A scores St 100.000000. Weighted points enter only as that ratio, B''s 100.000000 is its Sc, and 91.666667 is B''s combined score, below A''s 94.375000.'),
  ('procurement', 'beginner', 'final', null, 35, 'The technical method is left out of a combined score. What does the engine return?', '["The relative method, which the well services tender states, applied by default.", "The absolute method, the simpler of the two, applied until one is stated.", "Commercial score alone.", "A refusal naming technicalMethod, with no default."]'::jsonb, 3, 'The engine''s message is "technicalMethod must be ''relative'' (100 x T / Thigh) or ''absolute'' (T as scored); there is no default". It borrows no method from a fixture, prefers neither method, and drops no part of the score.'),
  ('procurement', 'beginner', 'final', null, 36, 'What is wrong with entering 120 as a bid''s technicalPercent in the combined score view?', '["Nothing, as a technical percentage above 100 simply sets Thigh.", "It exceeds the whole available score; the engine refuses any value above 100.", "Only that the engine caps it at 100 in silence before the ranking.", "The bid is then excluded from the ranking with a reason beside it."]'::jsonb, 1, 'No proposal can earn more than the whole available score, so the engine refuses the value with "bids[0].technicalPercent must be a number from 0 to 100". It computes no St above 100, caps nothing silently and returns no exclusion, since a bad input is refused before any ranking.'),
  ('procurement', 'beginner', 'final', null, 37, 'In the stated tie of T1, T2 and T3, T3''s receipt is moved to 08:00:00 on the same day. How are the three ranked?', '["T3 leads; T1 follows on receipt time, and T2 comes last on its code.", "T1, T2, T3 as before, since receipt time is used only between T1 and T2.", "T3, then T2, then T1.", "All three at rank 1."]'::jsonb, 0, 'With equal scores and costs the earlier receipt decides, so T3 at 08:00 ranks first; T1 and T2 share 09:00 and the bidder id puts T1 before T2 (engine run, tieBrokenBy null, earlier receipt, bidder id). Receipt time applies to every tied pair, the id orders ascending, and every ranking is strict.'),
  ('procurement', 'beginner', 'final', null, 38, 'WS3 is most advantageous at technical weight 0.7. Where does it rank on evaluated cost among the four responsive bids?', '["First, since the most advantageous bid is the bid that costs the company least.", "Second, behind WS5, as its omission is priced at an average of the others.", "Fourth, at 957990.000000", "Third, ahead of WS1, whose discount is offset by the early finish it offers."]'::jsonb, 2, 'Evaluated cost ascending, WS3 is last of the four at 957990.000000, with its nitrogen omission and one late week added to 918000.000000. The combined score weighs its best technical proposal at 0.7, which is how the fourth-lowest evaluated cost becomes most advantageous.'),
  ('procurement', 'beginner', 'final', null, 39, 'Every well services row of the evaluated cost ranking shows tieBrokenBy as null. What does that tell you?', '["The tie-break rules were switched off for this tender by its stated settings.", "No two evaluated costs tie, so no tie-break rule was used.", "Every bid tied, and the engine left the order as the bids were typed in.", "Receipt times were missing."]'::jsonb, 1, 'tieBrokenBy names the rule that ordered a row against the row above it, and it is null when no rule was needed. The four evaluated costs all differ, the tie-break is always on, and every bid carries a receipt time in the stated UTC form.'),
  ('procurement', 'beginner', 'final', null, 40, 'In the whole tender, WS2 is given a stated rejection reason and WS1 a completion of 11 weeks. Which bid is awarded under the combined basis?', '["WS5, as the rejection of two bids moves the award to the lowest evaluated cost.", "No bid at all.", "WS1, charged for lateness.", "WS3, still ahead of WS5, the one other bid left responsive."]'::jsonb, 3, 'WS2 and WS1 are both excluded at the commercial stage with their reasons, and the engine still awards WS3 (engine run). The change does reach WS3: its nitrogen is now priced from the one responsive bid left that quotes it, WS5, so its evaluated cost moves; Thigh stays with WS3 and Cmin with WS5, and WS3 keeps the lead. A bid beyond maxWeeks is excluded without a charge, and the award basis stays combined whatever is excluded.'),
  ('procurement', 'beginner', 'final', null, 41, 'Which function returns the refusal "bids has no bid left to score: every bid is rejected"?', '["rankTender, the combined score view of the envelope calculator.", "technicalEvaluation, when every bid fails a mandatory requirement or the pass mark.", "correctArithmetic, on a bad bill.", "evaluatedCosts, on late bids."]'::jsonb, 0, 'The refusal table lists this message under rankTender alone, with the field bids. A bid failing the technical envelope is returned with its reason, a line in discrepancy is corrected, and a bid beyond maxWeeks is excluded with its reason: each of those is a result.'),
  ('procurement', 'beginner', 'final', null, 42, 'The well services tender under a combined award excludes WS4 and WS6. Which bids does the ranking of the combined score hold?', '["All six, with WS4 and WS6 placed last on a combined score of 0.000000.", "WS3, WS1, WS2 and WS5, in that order.", "WS3, WS1, WS2, WS5 and WS4, as WS4 was scored and so can be ranked.", "WS3 and WS5 alone."]'::jsonb, 1, 'Only the responsive bids are ranked, and the engine orders them WS3 96.998434, WS1 95.806109, WS2 90.970882, WS5 87.647059. Excluded bids appear in the exclusions with their reasons and carry no combined score, WS4''s price was never opened, and every responsive bid is ranked.');
